      document.getElementById('addTemplateRow').addEventListener('click',function(){workspaceRows.push(blankWorkspaceRow());workspaceStatus='draft';workspaceTablePage=Math.floor((workspaceRows.length-1)/WORKSPACE_TABLE_PAGE_SIZE);renderWorkspaceTable();scheduleWorkspaceSave();var rowIndex=workspaceRows.length-1;var colIndex=workspaceToolId==='sipoc'?2:0;var input=document.querySelector('[data-w-row="'+rowIndex+'"][data-w-col="'+colIndex+'"]');if(input){input.focus();if(input.select)input.select();}toast(workspaceToolId==='sipoc'?'Paso de proceso agregado; escribe su nombre.':'Fila agregada; completa los campos relevantes');});
