      function updateCharter(){
        var filled=charterIds.filter(function(id){return charterValue(id).length>0;}).length;
        var problemOk=charterValue('charterProblem').length>=60&&/\d/.test(charterValue('charterProblem'));
        var goalOk=charterValue('charterGoal').length>=55&&/\d/.test(charterValue('charterGoal'))&&charterValue('charterEnd').length>0;
        var scopeOk=charterValue('charterScopeIn').length>=20&&charterValue('charterScopeOut').length>=20;
        var rolesOk=charterValue('charterSponsor').length>0&&charterValue('charterLeader').length>0;
        lastCharterScore=Math.min(100,Math.round((filled/charterIds.length)*70+[problemOk,goalOk,scopeOk,rolesOk].filter(Boolean).length*7.5));
        document.getElementById('charterScore').textContent=lastCharterScore+'%';document.getElementById('charterRing').style.setProperty('--p',lastCharterScore);
        document.getElementById('charterScoreLabel').textContent=lastCharterScore>=85?'Listo para revisión':lastCharterScore>=60?'Requiere ajustes':'Información incompleta';
        setCharterCheck('checkProblem',problemOk,'Problema cuantificado');setCharterCheck('checkGoal',goalOk,'Objetivo SMART');setCharterCheck('checkScope',scopeOk,'Alcance delimitado');setCharterCheck('checkRoles',rolesOk,'Gobierno asignado');
        setPreview('previewProject',charterValue('charterProject')||'Project Charter');setPreview('previewProblem',charterValue('charterProblem'));setPreview('previewBusiness',charterValue('charterBusiness'));setPreview('previewGoal',charterValue('charterGoal'));setPreview('previewScopeIn',charterValue('charterScopeIn'));setPreview('previewScopeOut',charterValue('charterScopeOut'));
        setPreview('previewMetric',[charterValue('charterMetric'),charterValue('charterBaseline')?'Línea base: '+charterValue('charterBaseline'):'',charterValue('charterTarget')?'Meta: '+charterValue('charterTarget'):''].filter(Boolean).join(' · '));
        setPreview('previewRoles',[charterValue('charterSponsor')?'Patrocinador: '+charterValue('charterSponsor'):'',charterValue('charterLeader')?'Líder: '+charterValue('charterLeader'):'',charterValue('charterEnd')?'Objetivo: '+charterValue('charterEnd'):''].filter(Boolean).join(' · '));
      }
      var charterAutosaveTimer;document.querySelectorAll('.charter-input').forEach(function(input){input.addEventListener('input',function(){updateCharter();clearTimeout(charterAutosaveTimer);charterAutosaveTimer=setTimeout(function(){var data={};charterIds.forEach(function(id){data[id]=document.getElementById(id).value;});localStorage.setItem(charterStorageKey(),JSON.stringify(data));},550);});});
      function loadCharterForProject(){var project=currentProjectStorageId();if(charterLoadedProject===project){updateCharter();return;}charterLoadedProject=project;charterIds.forEach(function(id){document.getElementById(id).value=charterDefaults[id];});try{var savedCharter=JSON.parse(localStorage.getItem(charterStorageKey()));if(savedCharter){charterIds.forEach(function(id){if(savedCharter[id]!=null)document.getElementById(id).value=savedCharter[id];});}}catch(e){}updateCharter();}
      try{if(!localStorage.getItem(charterStorageKey())&&localStorage.getItem('dmaicCharter'))localStorage.setItem(charterStorageKey(),localStorage.getItem('dmaicCharter'));}catch(e){}
      loadCharterForProject();
